css:
.cd-row-title{font-size:1.35em;font-weight:800;border-left:4px solid var(--cd-accent);padding-left:0.5em}
.cd-row:first-child .cd-row-title{font-size:1.7em}
.cd-row:first-child .cd-card{flex:0 0 max(var(--cd-card-min, 190px), calc((100% - (max(3, var(--cd-row-visible, 6) - 2) - 1) * var(--cd-gap, 16px)) / max(3, var(--cd-row-visible, 6) - 2)))}
.cd-row-prev,.cd-row-next{background:var(--cd-surface);border:1px solid var(--cd-border);color:var(--cd-text);border-radius:var(--cd-radius)}
.cd-card{background:var(--cd-surface);border:1px solid var(--cd-border);border-radius:var(--cd-radius);box-shadow:var(--cd-shadow);transition:transform var(--cd-duration) ease,box-shadow var(--cd-duration) ease}
.cd-card:hover{box-shadow:0 0 0 2px var(--cd-accent);transform:translateY(-2px)}
.cd-card-thumb{border-radius:var(--cd-radius)}
.cd-card-title{font-weight:700}
.cd-card-meta{color:var(--cd-muted)}
.cd-card-duration{border-radius:calc(var(--cd-radius) / 2);font-weight:700;background:var(--cd-surface);color:var(--cd-text);border:1px solid var(--cd-border)}
.cd-hero{background:linear-gradient(135deg,var(--cd-surface),var(--cd-bg));border:1px solid var(--cd-border);border-radius:calc(var(--cd-radius) * 1.5);box-shadow:var(--cd-shadow)}
.cd-hero-title{letter-spacing:-0.02em;font-weight:800}
.cd-hero-cta{background:var(--cd-accent);color:var(--cd-accent-text);border-radius:var(--cd-radius);font-weight:700}
